"""
Compatibility layer to extract tiktoken-based tokenization as a delegate.
This enables deferred binding time by decoupling GPT4Tokenizer from tiktoken
via composition rather than inheritance.
"""

from .base import Tokenizer
import tiktoken


class TiktokenTokenizer(Tokenizer):
    """A Tokenizer delegate wrapping tiktoken's cl100k_base tokenizer."""

    def __init__(self):
        super().__init__()
        self.enc = tiktoken.get_encoding("cl100k_base")
        mergeable_ranks = self.enc._mergeable_ranks

        # Recover merges from tiktoken's mergeable_ranks
        from .gpt4 import recover_merges, GPT4_SPLIT_PATTERN, GPT4_SPECIAL_TOKENS
        self.merges = recover_merges(mergeable_ranks)

        # Build vocab from merges (as in gpt4.py)
        vocab = {idx: bytes([idx]) for idx in range(256)}
        for (p0, p1), idx in self.merges.items():
            vocab[idx] = vocab[p0] + vocab[p1]
        self.vocab = vocab

        # Handle byte shuffle (as in gpt4.py)
        self.byte_shuffle = {i: mergeable_ranks[bytes([i])] for i in range(256)}
        self.inverse_byte_shuffle = {v: k for k, v in self.byte_shuffle.items()}

        # Register special tokens
        self.special_tokens = GPT4_SPECIAL_TOKENS
        self.inverse_special_tokens = {v: k for k, v in GPT4_SPECIAL_TOKENS.items()}

        # Set pattern (unused internally by TiktokenTokenizer but needed by base interface)
        self.pattern = GPT4_SPLIT_PATTERN

    def encode(self, text):
        # Encode using tiktoken, then remap via byte_shuffle
        ids = self.enc.encode(text)
        # Remap byte-level tokens using the same shuffle as GPT4Tokenizer
        ids = [self._remap_id(id_) for id_ in ids]
        # Rebuild tokens using vocab and re-encode to get final IDs (for consistency with existing encode/decode logic)
        # However, since tiktoken already gives final token IDs, we just need to adjust the byte shuffle.
        # Instead of re-encoding, adjust IDs directly based on byte_shuffle mapping.
        return ids

    def _remap_id(self, id_):
        if id_ < 256:
            return self.byte_shuffle[id_]
        return id_

    def decode(self, ids):
        # Remap ids back using inverse_byte_shuffle before passing to tiktoken
        ids = [self._inverse_remap_id(id_) for id_ in ids]
        return self.enc.decode(ids)

    def _inverse_remap_id(self, id_):
        if id_ < 256:
            return self.inverse_byte_shuffle[id_]
        return id_

    def train(self, text, vocab_size, verbose=False):
        raise NotImplementedError("TiktokenTokenizer is pretrained only")

    def save(self, file_prefix):
        raise NotImplementedError("TiktokenTokenizer cannot be saved.")

    def load(self, model_file):
        raise NotImplementedError("TiktokenTokenizer cannot be loaded.")
